$ErrorActionPreference='Stop';$pidPath=Join-Path $PSScriptRoot 'eval/.work/game-bridge.pid';if(-not(Test-Path $pidPath)){Write-Host 'No managed game bridge PID file was found.';exit 0};$bridgePid=[int](Get-Content -Raw $pidPath);$p=Get-Process -Id $bridgePid -ErrorAction SilentlyContinue;if($p-and$p.ProcessName-in@('pwsh','powershell')){Stop-Process -Id $bridgePid;Wait-Process -Id $bridgePid -ErrorAction SilentlyContinue;Write-Host "Game bridge stopped (PID $bridgePid)."}else{Write-Host 'Managed game bridge is not running.'};Remove-Item -LiteralPath $pidPath -Force
